// faceEmbeddings.js
import { Human } from '@vladmandic/human';

const human = new Human();

export async function getFaceEmbeddings(image, options = {}) {
    const {
        maxFaces = 100,
        minConfidence = 0.5
    } = options;

    const config = {
        detector: {
            maxDetected: maxFaces,
            minConfidence: minConfidence,
        },
        face: {
            description: { enabled: true }
        }
    };

    try {
        const result = await human.process(image, config);
        const faces = result.face || [];
        const embeddings = faces.map(face => Array.from(face.embedding));
        return embeddings;
    } catch (error) {
        console.error('Face embedding error:', error);
        throw new Error(`Failed to process image: ${error.message}`);
    }
}

